import { getCSVFromURL, remap } from '../../../../lib';

export class WaterQualityInspector {
    public data = {};

    public day = 24;

    public scale = 0.25
    public dataSampling = 4;
    public margin = 25;
    public ctx: CanvasRenderingContext2D;

    public m: number[] = [0, 0];
    public selVal: number = 0;
    public selID: number = 0;

    public dataRaw: string[] = [];

    public index = 0;
    public id = [
        'mass_concentration_of_blue_green_algae_in_sea_water_rfu (RFU)', // 0.10000000149011612   3.700000047683716
        'chlorophyll_fluorescence (RFU)',  // 0.10000000149011612   8
        'sea_water_turbidity (1)', // 0.009999999776482582   335.9800109863281
        'sea_water_temperature (K)', // 255.37222290039062   300.00555419921875
        'sea_water_ph_reported_on_total_scale (1)', // 255.37222290039062   300.00555419921875
    ];

    constructor(ctx: CanvasRenderingContext2D, i = 0) {
        this.ctx = ctx;
        this.index = i;
        document.onkeydown = (k) => {
            this.dataSampling++;
            // console.log(this.dataSampling)
        }
        getCSVFromURL(process.env.PUBLIC_URL + '/static/data/Watabot/obs_104_1928_d047_15c7.csv').then((d) => {
            const lines = d.split(/\r\n|\r|\n/g);
            this.dataRaw = lines;

            const index = lines[0].split(',');

            const dataDic = {}
            let needComputeData = true;
            for (let i = 0; i < index.length; ++i) {
                // console.log(index[i]);
                if (needComputeData && index[i] === 'time (UTC)') {
                    dataDic[index[i]] = [];
                    needComputeData = false;
                } else {
                    dataDic[index[i]] = new Float32Array(lines.length - 1);
                }
            }

            for (let i = 1; i < lines.length; ++i) {
                const row = lines[i].split(',');
                for (let j = 0; j < index.length; ++j) {
                    const theIndex = index.indexOf(index[j]);
                    if (theIndex !== -1) {
                        dataDic[index[j]][i - 1] = row[theIndex];
                    }
                }

            }
            this.data = dataDic;
            // console.log(dataDic);
            // const divContainer = this.ctx.canvas.parentElement;
            // const domRect = this.ctx.canvas.getBoundingClientRect();

            const div = document.createElement('div');
            div.style.zIndex = '1';
            div.style.color = '#000';
            div.style.fontSize = '11px';
            div.style.position = 'absolute';
            div.style.left = '10px';
            div.style.top = '5px';
            div.textContent = this.id[i];

            this.ctx.canvas.parentElement.appendChild(div);

            this.render(this.ctx);
        });
    }
    public Offset(v) {
        if (v < 0) {
            // this.offsetData -= this.offsetData * 0.5;
        } else {
            // this.offsetData += this.offsetData * 0.5;
        }
    }
    public wheel(e: WheelEvent) {
        if (e.deltaY < 0) {
            this.scale += this.scale * .25;
        } else {
            this.scale -= this.scale * .25;
        }
        this.scale = this.scale < 0.012 ? 0.012 : this.scale;
        // console.log(this.scale);
    }
    public mouseMove(x: number, y: number) {
        this.m[0] = x;
        this.m[1] = y;
    }
    public render(ctx: CanvasRenderingContext2D) {
        // console.log(this.m[0], this.m[1]);
        // console.trace();
        // ctx.save();
        // ctx.scale(-1,1)
        // ctx.translate(-this.ctx.canvas.width, 0)

        // console.log('o')

        // let index = ;

        const xP = (this.m[0] * -1) + this.ctx.canvas.width;


        let d = this.data[this.id[this.index]]; // sea_water_temperature (K) sea_water_turbidity (1)
        if (d === undefined) { return; }

        // console.log('this.index', this.index);

        vizBG(ctx, d, this.scale, this.day, this.margin);

        const domain = getMinMax(d, this.dataSampling);
        // console.log('domain', domain);

        ctx.lineWidth = 4;
        ctx.strokeStyle = '#000';
        this.vizData(ctx, d, domain, this.scale, this.day, this.dataSampling, this.margin, xP);

        // d = this.data['sea_water_turbidity (1)'];
        // vizData(ctx, d, '#0f0', this.scale, this.day, this.dataSampling, this.margin);

        // d = this.data['chlorophyll_fluorescence (RFU)'];
        // vizData(ctx, d, '#00f', this.scale, this.day, this.dataSampling, this.margin);

        // d = this.data['oxidation_reduction_potential (mV)'];
        // vizData(ctx, d, '#0ff', this.scale, this.day, this.dataSampling, this.margin);
        // ctx.restore();
        // ctx.scale(1,1);

        ctx.lineWidth = 0.5;

        ctx.beginPath();
        ctx.moveTo(xP, 0);
        ctx.lineTo(xP, this.ctx.canvas.height);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(xP, this.m[1], 1, 0, Math.PI * 2);
        ctx.fill();

        // let scaleLocalY = ctx.canvas.height - this.margin;
        
        // let id = Math.floor(xP * this.scale);
        // console.log('id', id);
        // const yP = remap(d[id], domain[0], domain[1], scaleLocalY, this.margin);
        // console.log(yP);

        ctx.fillStyle = '#f00';
        ctx.beginPath();
        ctx.arc(xP, this.selVal, 7, 0, Math.PI * 2);
        ctx.fill();

        // ctx.fillText(id[this.index], this.ctx.canvas.width * 0.5, 10);
    }
    public vizData = (ctx: CanvasRenderingContext2D, d, domain, scale, day, dataSampling, margin, mX) => {
        let scaleLocalY = ctx.canvas.height - margin;
        // console.log(ctx.canvas.height);

        ctx.beginPath();
        let x = margin;
        let y = remap(d[0], domain[0], domain[1], scaleLocalY, margin);

        mX = Math.floor((mX - margin) / scale);

        // console.log('mX', mX);

        ctx.moveTo(x, y);

        for (let i = 1; i < d.length; i += dataSampling) {
            x += 1;

            const xP = margin + (x * scale * dataSampling);

            let yP = 0 + margin;
            let val = 0;
            let key = 'max'; // max

            switch (key) {
                case 'mean':
                    for (let j = 0; j < dataSampling; ++j) {
                        val += d[i + j];
                    }

                    yP = val / dataSampling * scaleLocalY;
                    yP = remap(yP, domain[0], domain[1], scaleLocalY, margin);
                    ctx.lineTo(xP, yP);
                    break;

                default:
                    let hover = false;
                    for (let j = 0; j < dataSampling; ++j) {
                        const id = i + j;

                        // console.log(id);
                        
                        if (id === mX) {
                            hover = true;
                            this.selID = id;
                        }

                        if (val < d[id]) {
                            val = d[id];
                        }
                    }

                    yP = remap(val, domain[0], domain[1], scaleLocalY, margin); // offsetData;

                    if (hover) {
                        this.selVal = yP;
                        // console.log(this.selID);
                    }
                    // const dd = mX * dataSampling * scaleLocalY;
                    // if (dd === xP) {
                    //     console.log('yP', yP);
                    //     this.val = yP;
                    // }

                    ctx.lineTo(xP, yP);
                    break;
            }
        }
        ctx.stroke();

        // console.log(d[this.selID], this.dataRaw[this.selID]);

        // console.log(this.dataRaw[this.selID].split(',')[0]);

        ctx.save();

        ctx.scale(-1, 1);

        ctx.fillText(this.dataRaw[this.selID].split(',')[0], 10, 10);

        ctx.restore();
    };
}

