// sea_water_turbidity (1)
// sea_water_temperature (K)
// platform

const getMinMax = (d: number[], dataSampling: number) => {
    let min = Number.MAX_VALUE;
    let max = Number.MIN_VALUE;
    // dataSampling = 1;

    for (let i = 1; i < d.length; i += dataSampling) {
        let val = d[i];
        let key = 'max';
        switch (key) {
            case 'mean':
                for (let j = 0; j < dataSampling; ++j) {
                    min = min > val ? val : min;
                    max = max < val ? val : max;
                }
                break;
            default:
                for (let j = 0; j < dataSampling; ++j) {
                    min = min > val ? val : min;
                    max = max < val ? val : max;
                }
                break;
        }

    }
    return [min, max];
};

const vizBG = (ctx: CanvasRenderingContext2D, d, scale, day, margin) => {
    const hourRes = 12;

    ctx.setLineDash([2, 2]);
    ctx.lineWidth = 1;

    for (let i = 0; i < d.length; i++) {
        ctx.strokeStyle = `rgba(200, 200, 200, 0.8)`;

        if (scale > 0.1) {
            if (i % (hourRes * day) === 0) {
                const x = margin + i * scale;
                ctx.beginPath();
                ctx.moveTo(x, margin);
                ctx.lineTo(x, ctx.canvas.height - margin);
                ctx.stroke();
            }
        }

        ctx.strokeStyle = `rgba(0, 0, 255, 0.8)`;
        if (scale > 0.02) {
            if (i % (hourRes * day * 7) === 0) {
                const x = margin + i * scale;
                ctx.beginPath();
                ctx.moveTo(x, margin);
                ctx.lineTo(x, ctx.canvas.height - margin);
                ctx.stroke();
                // console.log(i)
            }
        }

        ctx.strokeStyle = `rgba(0, 255, 0, 0.8)`;
        if (i % (hourRes * day * 30) === 0) {
            const x = margin + i * scale;
            ctx.beginPath();
            ctx.moveTo(x, margin);
            ctx.lineTo(x, ctx.canvas.height - margin);
            ctx.stroke();
            // console.log(i)
        }

    }
    ctx.setLineDash([]);
};